	@Inject
	public BddGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pModel = new ModelElements();
		this.pEntity = new EntityElements();
		this.pState = new StateElements();
		this.pProperty = new PropertyElements();
		this.pScenario = new ScenarioElements();
		this.pTrigger = new TriggerElements();
		this.pWhenTrigger = new WhenTriggerElements();
		this.pWheneverTrigger = new WheneverTriggerElements();
		this.pEvent = new EventElements();
		this.pTimeEvent = new TimeEventElements();
		this.pEndEvent = new EndEventElements();
		this.eTimeUnit = new TimeUnitElements();
		this.pCondition = new ConditionElements();
		this.pStateCondition = new StateConditionElements();
		this.pPropCondition = new PropConditionElements();
		this.pBetweenCondition = new BetweenConditionElements();
		this.pEffect = new EffectElements();
		this.pStateEffect = new StateEffectElements();
		this.pAssignEffect = new AssignEffectElements();
		this.pDeltaEffect = new DeltaEffectElements();
		this.eDeltaOp = new DeltaOpElements();
		this.pRandomEffect = new RandomEffectElements();
		this.pPropRef = new PropRefElements();
		this.pValue = new ValueElements();
		this.pPropValue = new PropValueElements();
		this.pNumberValue = new NumberValueElements();
		this.eComp = new CompElements();
		this.pRequirement = new RequirementElements();
		this.pTimeBound = new TimeBoundElements();
		this.pCheck = new CheckElements();
		this.pCheckQuery = new CheckQueryElements();
		this.pNeverCheck = new NeverCheckElements();
		this.pMaxCheck = new MaxCheckElements();
		this.pMinCheck = new MinCheckElements();
		this.pReqCond = new ReqCondElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("dk.sdu.Bdd".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
